html:
{%- set seen = [] -%}
{%- for row in doc.items -%}
{%- if row.ucc128 and row.ucc128 not in seen -%}
{%- set _ = seen.append(row.ucc128) -%}
<div class="label-preview">
  <img src="data:image/png;base64,{{ labelary_api(frappe.get_doc('Handling Unit', row.ucc128), 'Pure Hockey ASN ZPL', {'dpmm': 8, 'width': 4, 'height': 6}) }}" />
</div>
{%- endif -%}
{%- endfor -%}

<style>
.label-preview { margin: 8px 0; }
.label-preview img { display: block; max-width: 100%; }
</style>
